using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using EfFixtures;
using Microsoft.EntityFrameworkCore;

public static class PostQueries
{
    public static async Task<List<string>> GetPopularPostTitles(
        BlogContext context,
        CancellationToken cancellationToken)
    {
        IQueryable<string> titlesQuery =
            from post in context.Posts
            where post.Views > 100
            orderby post.Views descending
            select post.Title;

        List<string> popularTitles = await titlesQuery.ToListAsync(cancellationToken);
        return popularTitles;
    }
}
